	function isArabicOrNameLike(value) {
		return /[\u0600-\u06FF]/.test(value) || /\s/.test(value.trim());
	}
	function parseBulkEntries(text) {
		const lines = normalizeDigits(text).split(/\r?\n/);
		const seenCodes = new Set();
		const codes = [];
		const names = [];
		const duplicates = [];
		const invalid = [];
		let totalTokens = 0;
		let seq = 0;
		const pushCode = (raw, token) => {
			totalTokens++;
			const code = token.toUpperCase();
			if (!CODE_RE.test(code)) {
				invalid.push(raw.trim() || token);
				return;
			}
			if (seenCodes.has(code)) {
				duplicates.push(code);
				return;
			}
			seenCodes.add(code);
			codes.push({
				kind: "code",
				key: `c-${++seq}-${code}`,
				raw: raw.trim() || code,
				code
			});
		};
		const pushName = (raw) => {
			const query = raw.trim().replace(/\s+/g, " ");
			if (!query) return;
			totalTokens++;
			names.push({
				kind: "name",
				key: `n-${++seq}-${query}`,
				raw: query,
				query
			});
		};
		for (const line of lines) {
			const trimmed = line.trim();
			if (!trimmed) continue;
			const hasArabic = /[\u0600-\u06FF]/.test(trimmed);
			const parts = hasArabic ? [trimmed] : trimmed.split(/[,\u060C;\u061B]+/).map((p) => p.trim()).filter(Boolean);
			const effectiveParts = parts.length ? parts : [trimmed];
			for (const part of effectiveParts) {
				const upper = part.toUpperCase();
				if (CODE_RE.test(upper) && !/[\u0600-\u06FF]/.test(part)) {
					pushCode(part, upper);
					continue;
				}
				if (!hasArabic) {
					const spaceParts = part.split(/\s+/).map((p) => p.trim()).filter(Boolean);
					if (spaceParts.length > 1 && spaceParts.every((p) => CODE_RE.test(p.toUpperCase()))) {
						for (const sp of spaceParts) pushCode(sp, sp.toUpperCase());
						continue;
					}
				}
				if (/^[A-Z0-9_-]+$/i.test(part) && !isArabicOrNameLike(part) && part.length < 3) {
					totalTokens++;
					invalid.push(part);
					continue;
				}
				pushName(part);
			}
		}
		return {
			codes,
			names,
			duplicates,
			invalid,
			totalTokens
		};
	}
	async function searchStudents(query, lessonId) {
		const scan = detectScanForm();
		if (!scan?.studentsUrl) return { error: "رابط البحث عن الطلاب غير متاح في الصفحة." };
		try {
			const url = new URL(scan.studentsUrl, location.href);
			url.searchParams.set("lesson_id", lessonId);
			url.searchParams.set("q", query);
			url.searchParams.set("limit", "100");
			const response = await fetch(url.href, {
				credentials: "same-origin",
				headers: { Accept: "application/json" }
			});
			if (!response.ok) return { error: `تعذر البحث (${response.status})` };
			const json = await response.json();
			if (!Array.isArray(json)) return { error: "استجابة بحث غير متوقعة." };
			if (json.length >= 100) return { tooMany: true };
			return json.map((item) => {
				const obj = item && typeof item === "object" ? item : {};
				const profile = obj.student_profile && typeof obj.student_profile === "object" ? obj.student_profile : {};
				const code = String(profile.student_code ?? obj.username ?? "").trim();
				return {
					id: String(obj.id ?? ""),
					name: String(obj.name ?? "").trim(),
					code
				};
			}).filter((c) => c.code || c.name);
		} catch (error) {
			return { error: error instanceof Error ? error.message : "تعذر الاتصال أثناء البحث." };
		}
	}
	function candidateMatchesQuery(candidate, query) {
		const nq = normalizeName(query);
		if (!nq) return false;
		const name = normalizeName(candidate.name);
		const code = normalizeName(candidate.code);
		return name === nq || code === nq || name.includes(nq) || nq.includes(name);
	}
	async function resolveNameEntry(row, lessonId) {
		const query = row.query.trim();
		if (!query) return {
			...row,
			status: "not-found",
			candidates: [],
			message: "الاسم فارغ."
		};
		const result = await searchStudents(query, lessonId);
		if ("error" in result) return {
			...row,
			status: "error",
			candidates: [],
			message: result.error
		};
		if ("tooMany" in result) return {
			...row,
			status: "too-many",
			candidates: [],
			message: "نتائج كثيرة جدًا — حدّد الاسم أكثر أو استخدم الكود."
		};
		const candidates = result;
		if (!candidates.length) return {
			...row,
			status: "not-found",
			candidates: [],
			message: "لم يتم العثور على طالب مطابق."
		};
		const exact = candidates.filter((c) => {
			const nq = normalizeName(query);
			return normalizeName(c.name) === nq || normalizeName(c.code) === nq;
		});
		if (exact.length === 1) {
			const c = exact[0];
			return {
				...row,
				status: "resolved",
				code: c.code,
				studentName: c.name,
				candidates,
				message: `تم التعرف: ${c.name} (${c.code || "بدون كود"})`
			};
		}
		if (candidates.length === 1) {
			const c = candidates[0];
			if (candidateMatchesQuery(c, query)) return {
				...row,
				status: "resolved",
				code: c.code,
				studentName: c.name,
				candidates,
				message: `مطابقة واحدة: ${c.name} (${c.code || "بدون كود"})`
			};
		}
		return {
			...row,
			status: "ambiguous",
			candidates,
			message: candidates.length > 1 ? "يوجد أكثر من طالب مطابق — اختر الصحيح." : "تعذّر التأكد من المطابقة."
		};
	}
	function sleep(ms) {
		return new Promise((resolve) => setTimeout(resolve, ms));
	}
	function waitForCode(code, timeoutMs) {
		const undoRedo = getUndoRedoController();
		return new Promise((resolve) => {
			let done = false;
			const timer = window.setTimeout(() => {
				if (done) return;
				done = true;
				off();
				resolve("timeout");
			}, timeoutMs);
			const off = undoRedo.onAttendance((event) => {
				if (done) return;
				const recordCode = String(event.record.studentCode ?? event.record.username ?? "").toUpperCase();
				if (recordCode && recordCode !== code.toUpperCase()) return;
				done = true;
				window.clearTimeout(timer);
				off();
				resolve(event);
			});
		});
	}
	function submitScanForm(form, input) {
		input.focus();
		input.dispatchEvent(new Event("input", { bubbles: true }));
		input.dispatchEvent(new Event("change", { bubbles: true }));
		if (typeof form.requestSubmit === "function") {
			form.requestSubmit();
			return;
		}
		const submit = form.querySelector("button[type=\"submit\"], input[type=\"submit\"], button:not([type])");
		if (submit) {
			submit.click();
			return;
		}
		form.dispatchEvent(new Event("submit", {
			bubbles: true,
			cancelable: true
		}));
	}
	function getCsrfToken() {
		return (document.querySelector("meta[name=\"csrf-token\"]")?.content ?? "").trim();
	}
	async function submitSchoolAttendance(code, lessonId, override) {
		const csrf = getCsrfToken();
		if (!csrf) return {
			ok: false,
			message: "تعذّر قراءة CSRF token من الصفحة."
		};
		const status = override?.status ?? "paid";
		const body = {
			student: code,
			lesson_id: Number(lessonId),
			source: "manual",
			payment_status: status
		};
		if ((status === "partial" || status === "discounted") && override?.amountPaid != null) body.amount_paid = override.amountPaid;
		if (override?.note) body.payment_note = override.note;
		try {
			const response = await fetch("/attendance", {
				method: "POST",
				credentials: "same-origin",
				headers: {
					"Content-Type": "application/json",
					"Accept": "application/json",
					"X-CSRF-TOKEN": csrf
				},
				body: JSON.stringify(body)
			});
			const data = await response.json();
			if (!response.ok) {
				const errors = data.errors;
				return {
					ok: false,
					message: String(data.message ?? (errors ? Object.values(errors).flat()[0] : "") ?? "خطأ غير معروف")
				};
			}
			return {
				ok: true,
				data
			};
		} catch (err) {
			return {
				ok: false,
				message: err instanceof Error ? err.message : "تعذّر الاتصال بالخادم."
			};
		}
	}
	async function runBulkAttendance(options) {
		const undoRedo = getUndoRedoController();
		const timeoutMs = options.timeoutMs ?? 1e4;
		const paymentMode = options.paymentMode ?? "center";
		const overrideMap = new Map((options.paymentOverrides ?? []).map((o) => [o.studentCode.toUpperCase(), o]));
		const rows = [];
		let created = 0;
		let duplicates = 0;
		let skipped = 0;
		let failed = 0;
		let stopped = false;
		for (const entry of options.entries) {
			const code = entry.code.toUpperCase();
			if (options.signal.stop) {
				stopped = true;
				break;
			}
			if (undoRedo.knownRecordCodes.includes(code)) {
				const row = {
					code,
					label: entry.label,
					status: "skipped-known",
					message: "مسجّل بالفعل",
					at: Date.now()
				};
				rows.push(row);
				skipped++;
				options.onRow(row);
				continue;
			}
			if (paymentMode === "school") {
				const lessonId = options.lessonId ?? currentLessonIdFromPage() ?? "";
				if (!lessonId) {
					const row = {
						code,
						label: entry.label,
						status: "error",
						message: "رقم الحصة غير معروف.",
						at: Date.now()
					};
					rows.push(row);
					failed++;
					options.onRow(row);
					stopped = true;
					break;
				}
				const override = overrideMap.get(code);
				const wait = waitForCode(code, timeoutMs);
				const result = await submitSchoolAttendance(code, lessonId, override);
				if (!result.ok) {
					const row = {
						code,
						label: entry.label,
						status: "error",
						message: result.message,
						at: Date.now()
					};
					rows.push(row);
					failed++;
					options.onRow(row);
					if (!result.message.includes("مسجّل") && !result.message.includes("سبق")) {
						stopped = true;
						break;
					}
					continue;
				}
				const event = await wait;
				if (event === "timeout") {
					const row = {
						code,
						label: entry.label,
						status: "created",
						message: "تم التسجيل (تأكيد المراقب لم يصل)",
						at: Date.now()
					};
					rows.push(row);
					created++;
					options.onRow(row);
				} else if (event.type === "add") {
					const payLabel = override ? {
						paid: "كامل",
						partial: "جزئي",
						discounted: "مخفض",
						forgotten: "نسي الفلوس"
					}[override.status] : "كامل";
					const row = {
						code,
						label: entry.label,
						status: "created",
						message: `تم التسجيل — ${payLabel}`,
						recordId: event.record.id,
						at: Date.now()
					};
					rows.push(row);
					created++;
					options.onRow(row);
				} else if (event.type === "duplicate") {
					const row = {
						code,
						label: entry.label,
						status: "duplicate",
						message: "مسجّل بالفعل",
						recordId: event.record.id,
						at: Date.now()
					};
					rows.push(row);
					duplicates++;
					options.onRow(row);
				} else {
					const row = {
						code,
						label: entry.label,
						status: "error",
						message: "استجابة غير متوقعة",
						at: Date.now()
					};
					rows.push(row);
					failed++;
					options.onRow(row);
				}
				if (!options.signal.stop) await sleep(150);
				continue;
			}
			const scan = detectScanForm();
			if (!scan) {
				const row = {
					code,
					label: entry.label,
					status: "error",
					message: "تعذّر العثور على نموذج/حقل الإدخال",
					at: Date.now()
				};
				rows.push(row);
				failed++;
				options.onRow(row);
				stopped = true;
				break;
			}
			scan.input.value = code;
			const wait = waitForCode(code, timeoutMs);
			submitScanForm(scan.form, scan.input);
			const result = await wait;
			if (result === "timeout") {
				const row = {
					code,
					label: entry.label,
					status: "timeout",
					message: "لم يصل تأكيد من الخادم",
					at: Date.now()
				};
				rows.push(row);
				failed++;
				options.onRow(row);
				stopped = true;
				break;
			}
			if (result.type === "add") {
				const row = {
					code,
					label: entry.label,
					status: "created",
					message: "تم التسجيل",
					recordId: result.record.id,
					at: Date.now()
				};
				rows.push(row);
				created++;
				options.onRow(row);
			} else if (result.type === "duplicate") {
				const row = {
					code,
					label: entry.label,
					status: "duplicate",
					message: "مسجّل بالفعل",
					recordId: result.record.id,
					at: Date.now()
				};
				rows.push(row);
				duplicates++;
				options.onRow(row);
			} else {
				const row = {
					code,
					label: entry.label,
					status: "error",
					message: "استجابة غير متوقعة",
					at: Date.now()
				};
				rows.push(row);
				failed++;
				options.onRow(row);
			}
			if (!options.signal.stop) await sleep(150);
		}
		if (options.signal.stop && !stopped) stopped = true;
		return {
			rows,
			created,
			duplicates,
			skipped,
			failed,
			stopped
		};
	}
